import { useState, useRef, useEffect } from 'react';
import './App.css';
import songs from './songs';

function App() {
  const [currentSongIndex, setCurrentSongIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const audioRef = useRef(null);

  const currentSong = songs[currentSongIndex];

  // Play or pause the song
  const togglePlay = () => {
    if (isPlaying) {
      audioRef.current.pause();
    } else {
      audioRef.current.play();
    }
    setIsPlaying(!isPlaying);
  };

  // Go to previous song
  const prevSong = () => {
    setCurrentSongIndex((prevIndex) => 
      prevIndex === 0 ? songs.length - 1 : prevIndex - 1
    );
  };

  // Go to next song
  const nextSong = () => {
    setCurrentSongIndex((prevIndex) => 
      prevIndex === songs.length - 1 ? 0 : prevIndex + 1
    );
  };

  // Update progress bar
  const updateProgress = () => {
    if (audioRef.current) {
      setCurrentTime(audioRef.current.currentTime);
      setDuration(audioRef.current.duration);
    }
  };

  // Set progress when clicking on progress bar
  const setProgress = (e) => {
    const width = e.currentTarget.clientWidth;
    const clickX = e.nativeEvent.offsetX;
    const duration = audioRef.current.duration;
    audioRef.current.currentTime = (clickX / width) * duration;
  };

  // Auto-play when song changes
  useEffect(() => {
    if (isPlaying && audioRef.current) {
      audioRef.current.play();
    }
  }, [currentSongIndex, isPlaying]);

  const progressPercent = duration ? (currentTime / duration) * 100 : 0;

  return (
    <div className="App">
      <div className={`music-container ${isPlaying ? 'play' : ''}`}>
        <div className="music-info">
          <h4 id="title">{currentSong.name}</h4>
          <div className="progress-container" onClick={setProgress}>
            <div className="progress" style={{ width: `${progressPercent}%` }}></div>
          </div>
        </div>

        <audio 
          ref={audioRef} 
          src={currentSong.audio}
          onTimeUpdate={updateProgress}
          onEnded={nextSong}
        ></audio>

        <div className="img-container">
          <img src={currentSong.cover} alt="music-cover" />
        </div>

        <div className="navigation">
          <button className="action-btn" onClick={prevSong}>
            <i className="fas fa-backward"></i>
          </button>
          <button className="action-btn action-btn-big" onClick={togglePlay}>
            <i className={`fas fa-${isPlaying ? 'pause' : 'play'}`}></i>
          </button>
          <button className="action-btn" onClick={nextSong}>
            <i className="fas fa-forward"></i>
          </button>
        </div>
      </div>
    </div>
  );
}

export default App;
